// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Initialize font at module level (handles delayRender/continueRender internally)
const { fontFamily: interFamily } = loadInter();



export type SaaSJourneyProps = Record<string, any>;

// Helper Component: Clean, geometric, vector-based human silhouette leaning into a climb
const ClimberFigure: React.FC<{
  size: number;
  color: string;
  style?: React.CSSProperties;
}> = ({ size, color, style }) => (
  <svg
    width={size}
    height={size * 1.5}
    viewBox="0 0 24 36"
    style={{
      ...style,
      overflow: "visible",
      filter: "drop-shadow(0px 8px 12px rgba(0,0,0,0.3))",
      transition: "none",
    }}
  >
    {/* Head */}
    <circle cx="15" cy="6" r="4.5" fill={color} style={{ transition: "none" }} />
    {/* Body leaning forward */}
    <path
      d="M 12.5 12
         C 17.5 11.5, 19.5 15, 18.5 19
         L 16.5 28
         C 15.5 32, 10.5 32, 11.5 28
         L 12.5 19
         C 12.5 15, 10.5 15, 9.5 13
         Z"
      fill={color}
      style={{ transition: "none" }}
    />
    {/* Reaching Arm */}
    <path
      d="M 15 14
         C 18 13, 23 9, 24 7
         C 25 5.5, 23 4, 21.5 5.5
         C 19 8, 15.5 10.5, 14 11.5
         Z"
      fill={color}
      style={{ transition: "none" }}
    />
  </svg>
);

const SaaSJourney: React.FC<SaaSJourneyProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 8,
  gradientStart = "#000000",
  gradientEnd = "#0f2f23",
  accentColor = "#81a969",
  highlightColor = "#ffffff",
  mountainBaseColor = "#0a2219",
  mountainPeakColor = "#113527",
  label = "MOMENTUM",
  showLabel = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser Safety / Logic extraction
  const bgStyle: React.CSSProperties = transparentBackground
    ? { backgroundColor: `${backgroundColor}00` }
    : { background: `radial-gradient(circle at 80% 20%, ${gradientEnd} 0%, ${gradientStart} 100%)` };

  // Responsive Math Setup
  // Slope calculations: starts bottom-left, ends top-right
  const y1 = height * 0.85; // Bottom Left
  const y2 = height * 0.25; // Top Right
  const slopeAngle = Math.atan2(y2 - y1, width) * (180 / Math.PI); // Used for rotating figures slightly

  // Mountain Paths
  const backgroundMountainPath = `M 0,${height} L 0,${y1 - height * 0.1} L ${width * 0.7},${y2 - height * 0.05} L ${width},${height} Z`;
  const foregroundMountainPath = `M 0,${height} L 0,${y1} L ${width},${y2} L ${width},${height} Z`;

  // Animation Timings based on total duration
  const totalFrames = durationInSeconds * fps;
  
  // Progress values for the dotted trail mask
  const trailProgress = interpolate(frame, [0, totalFrames * 0.4], [0, width], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Glow Animation (appears as progress is made)
  const glowOpacity = interpolate(
    frame,
    [totalFrames * 0.4, totalFrames * 0.8],
    [0, 0.4],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const glowScale = spring({
    frame: Math.max(0, frame - totalFrames * 0.4),
    fps,
    config: { damping: 100, mass: 2 },
  });

  // Figure Data: Positions, Timings, and Colors representing the 3 phases
  const figures = [
    // PHASE 1 (Start) - Isolated, low on slope
    { id: "p1-1", progress: 0.15, appearAt: 0.05, sizeMult: 1.0, color: highlightColor, yOffset: 0 },
    
    // PHASE 2 (Mid) - Eye moves up, 2 more figures
    { id: "p2-1", progress: 0.42, appearAt: 0.25, sizeMult: 0.85, color: accentColor, yOffset: -height * 0.01 },
    { id: "p2-2", progress: 0.48, appearAt: 0.30, sizeMult: 0.9, color: highlightColor, yOffset: height * 0.015 },
    
    // PHASE 3 (Top) - Group at the peak, momentum
    { id: "p3-1", progress: 0.75, appearAt: 0.50, sizeMult: 0.8, color: accentColor, yOffset: height * 0.02 },
    { id: "p3-2", progress: 0.80, appearAt: 0.55, sizeMult: 0.75, color: highlightColor, yOffset: -height * 0.01 },
    { id: "p3-3", progress: 0.83, appearAt: 0.60, sizeMult: 0.8, color: accentColor, yOffset: height * 0.01 },
    { id: "p3-4", progress: 0.88, appearAt: 0.65, sizeMult: 0.85, color: highlightColor, yOffset: -height * 0.005 },
  ];

  // Title Animations
  const titleOpacity = interpolate(frame, [15, 45], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(frame, [15, 45], [height * 0.15, height * 0.1], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ ...bgStyle, fontFamily: interFamily, transition: "none" }}>
      
      {/* Mountain Background Layer */}
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0, transition: "none" }}>
        <path d={backgroundMountainPath} fill={mountainBaseColor} style={{ transition: "none" }} />
      </svg>

      {/* Glow Highlight at the Peak */}
      <div
        style={{
          position: "absolute",
          left: width * 0.8 - (width * 0.6) / 2,
          top: y2 - height * 0.2 - (width * 0.6) / 2,
          width: width * 0.6,
          height: width * 0.6,
          background: `radial-gradient(circle, ${highlightColor} 0%, rgba(255,255,255,0) 60%)`,
          opacity: glowOpacity,
          transform: `scale(${0.8 + glowScale * 0.2})`,
          mixBlendMode: "screen",
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Dotted Route/Trail */}
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0, transition: "none" }}>
        <defs>
          <clipPath id="trailClip">
            <rect x="0" y="0" width={trailProgress} height={height} style={{ transition: "none" }} />
          </clipPath>
        </defs>
        <path
          d={`M 0,${y1 - height * 0.02} L ${width},${y2 - height * 0.02}`}
          stroke={accentColor}
          strokeWidth={Math.max(4, width * 0.005)}
          strokeDasharray={`${width * 0.01} ${width * 0.02}`}
          strokeOpacity={0.6}
          fill="none"
          clipPath="url(#trailClip)"
          style={{ transition: "none" }}
        />
      </svg>

      {/* Mountain Foreground Layer */}
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0, transition: "none" }}>
        <path d={foregroundMountainPath} fill={mountainPeakColor} style={{ transition: "none" }} />
        {/* Subtle top edge highlight to the mountain */}
        <path 
          d={`M 0,${y1} L ${width},${y2}`} 
          stroke={highlightColor} 
          strokeWidth={2} 
          strokeOpacity={0.15} 
          fill="none" 
          style={{ transition: "none" }} 
        />
      </svg>

      {/* Figures (Journey rendering) */}
      {figures.map((fig) => {
        const appearFrame = totalFrames * fig.appearAt;
        const relativeFrame = Math.max(0, frame - appearFrame);
        
        // Spring animation for popping in
        const popScale = spring({
          frame: relativeFrame,
          fps,
          config: { damping: 14, mass: 0.8, stiffness: 120 },
        });

        // Subtle upward movement as they climb over time
        const climbMovement = interpolate(
          relativeFrame,
          [0, totalFrames],
          [0, 0.03], // Move 3% further up the slope
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const currentProgress = Math.min(fig.progress + climbMovement, 1);
        
        // Base coordinate calculation along the slope
        const xPos = width * currentProgress;
        const baseY = y1 + currentProgress * (y2 - y1);
        
        const figureSize = width * 0.06 * fig.sizeMult;
        
        // Opacity fade-in to smooth out the spring pop
        const figOpacity = interpolate(relativeFrame, [0, 10], [0, 1], { extrapolateRight: "clamp" });

        return (
          <div
            key={fig.id}
            style={{
              position: "absolute",
              left: xPos - figureSize / 2,
              // Anchor the figure to its feet (baseY) and apply the aesthetic vertical offset
              top: baseY - (figureSize * 1.5) + fig.yOffset,
              transform: `scale(${popScale}) rotate(${slopeAngle * 0.3}deg)`,
              opacity: figOpacity,
              transformOrigin: "bottom center",
              transition: "none",
            }}
          >
            <ClimberFigure size={figureSize} color={fig.color} />
          </div>
        );
      })}

      {/* Optional Top Left Label / Typography */}
      {showLabel && (
        <div
          style={{
            position: "absolute",
            left: width * 0.08,
            top: titleY,
            opacity: titleOpacity,
            display: "flex",
            flexDirection: "column",
            gap: height * 0.01,
            transition: "none",
          }}
        >
          <div 
            style={{ 
              width: width * 0.05, 
              height: 4, 
              backgroundColor: accentColor, 
              borderRadius: 2,
              transition: "none" 
            }} 
          />
          <h1
            style={{
              color: highlightColor,
              fontSize: width * 0.04,
              fontWeight: 800,
              letterSpacing: width * 0.01,
              margin: 0,
              textTransform: "uppercase",
              transition: "none",
            }}
          >
            {label}
          </h1>
        </div>
      )}

    </AbsoluteFill>
  );
};

export default SaaSJourney;